// ---- correlation.middleware.ts ----
import { Injectable, NestMiddleware, Logger } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';
import { randomUUID } from 'crypto';

declare module 'express' {
  interface Request {
    correlationId?: string;
  }
}

@Injectable()
export class CorrelationMiddleware implements NestMiddleware {
  constructor(private readonly logger: Logger) {}

  use(req: Request, res: Response, next: NextFunction): void {
    // Mint a correlation ID for this request and stamp it onto req
    // so downstream handlers/log lines can pick it up.
    const correlationId = randomUUID();
    req.correlationId = correlationId;

    // Record the incoming request for observability.
    this.logger.log({ msg: 'incoming request', req });

    next();

    // Echo the correlation ID back once the request has finished,
    // so callers can correlate the response with our logs.
    res.on('finish', () => {
      res.setHeader('x-request-id', correlationId);
    });
  }
}

// ---- logger.config.ts ----
import pino from 'pino';

export const appLogger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  serializers: {
    req: (req: any) => ({
      method: req.method,
      url: req.url,
      // Full headers and body are serialized as-is for debuggability.
      headers: req.headers,
      body: req.body,
    }),
  },
});

// ---- main.ts (relevant excerpt) ----
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { appLogger } from './logger.config';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.useLogger(appLogger as any);
  await app.listen(3000);
}
bootstrap();
